[
  {
    "statement": "Several management strategies for uncropped field margins have been shown to effectively support bumblebees on European farmland.",
    "citations": []
  },
  {
    "statement": "Sowing uncropped margins with agricultural nectar and pollen mixes attracts significantly more foraging bumblebees than naturally regenerated, grassy or cropped margins.",
    "citations": []
  },
  {
    "statement": "Agricultural nectar and pollen mixes containing perennial leguminous flowering plants are particularly effective at attracting foraging bumblebees.",
    "citations": []
  },
  {
    "statement": "The value of agricultural nectar and pollen mixes degrades over time, requiring the mixes to be re-sown every few years.",
    "citations": []
  },
  {
    "statement": "Native wildflower seed mixes support a higher abundance and species richness of bumblebees compared to cropped edges.",
    "citations": []
  },
  {
    "statement": "Perennial leguminous herbs provide important forage sources for bumblebees, especially for long-tongued species.",
    "citations": []
  },
  {
    "statement": "Naturally regenerated uncropped margins can support more bumblebees than cropped margins.",
    "citations": []
  },
  {
    "statement": "The value of naturally regenerated margins for bumblebees is often based on thistle species that are considered pernicious weeds.",
    "citations": []
  },
  {
    "statement": "The benefits for bumblebees from naturally regenerated uncropped margins are not consistent from year to year.",
    "citations": []
  },
  {
    "statement": "Providing grass strips at field margins can enhance bumblebee abundance and diversity.",
    "citations": []
  },
  {
    "statement": "Grass margins that are 6 meters wide have shown positive effects for bumblebees.",
    "citations": []
  },
  {
    "statement": "Conservation headlands, which are unsprayed field margins within crops, do not attract more foraging bumblebees than conventional fields.",
    "citations": []
  },
  {
    "statement": "During spring, rough grassland areas in field margins attract nest-searching queen bumblebees at higher densities than other habitat types.",
    "citations": []
  }
]

