[
  {
    "statement": "Ten trials from Europe and North America have monitored wild bees foraging on phacelia (Phacelia tanacetifolia) planted on farmland.",
    "citations": []
  },
  {
    "statement": "Nine trials monitoring phacelia on farmland found substantial numbers of foraging wild bees, particularly bumblebees (Bombus spp.).",
    "citations": []
  },
  {
    "statement": "Six trials recorded bee species richness on phacelia ranging from 8 to 35 species.",
    "citations": []
  },
  {
    "statement": "One replicated trial showed that phacelia is not very attractive to wild bees in Greece.",
    "citations": []
  },
  {
    "statement": "The effectiveness of phacelia as a floral resource for wild bees shows significant geographic variation.",
    "citations": []
  },
  {
    "statement": "Studies found that wildflower strips sown with phacelia had higher species richness or diversity of butterflies and moths compared to other flower species.",
    "citations": []
  },
  {
    "statement": "Three replicated studies found that sowing phacelia had negative impacts or no effects on overall biodiversity.",
    "citations": []
  }
